import{_ as i,o as a,c as n,a4 as e}from"./chunks/framework.B-wJupoK.js";const l="/assets/PixPin_2024-12-26_23-21-28.DNpfstBt.gif",t="/assets/PixPin_2024-12-27_08-37-11.DXv4g2uE.gif",p="/assets/PixPin_2024-12-27_08-40-59.Clg2DbGZ.gif",h="/assets/PixPin_2024-12-27_08-43-55.BLJ6OWfb.gif",b=JSON.parse(`{"title":"HarmonyOS Next 弹窗系列教程（3）","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/HarmonyOS Next 弹窗系列教程/HarmonyOS Next 弹窗系列教程（3）/HarmonyOS Next 弹窗系列教程（3）.md","filePath":"鸿蒙开发技巧/HarmonyOS Next 弹窗系列教程/HarmonyOS Next 弹窗系列教程（3）/HarmonyOS Next 弹窗系列教程（3）.md","lastUpdated":1748912459000,"__rawMarkdown":"# HarmonyOS Next 弹窗系列教程（3）\\n\\n## 选择器弹窗 (PickerDialog) 介绍\\n\\n\\n\\n选择器弹窗通常用于在用户进行某些操作（如点击按钮）时显示特定的信息或选项。让用户可以进行选择提供的固定的内容。\\n\\n以下内容都属于选择器弹窗：\\n\\n1. 日历选择器弹窗 (CalendarPickerDialog)\\n2. 日期滑动选择器弹窗 (DatePickerDialog)\\n3. 时间滑动选择器弹窗 (TimePickerDialog)\\n4. 文本滑动选择器弹窗 (TextPickerDialog)\\n\\n### 日历选择器弹窗 (CalendarPickerDialog)\\n\\n日历选择器弹窗提供日历视图，包含年、月和星期信息，通过[CalendarPickerDialog](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V5/ts-methods-calendarpicker-dialog-V5)接口实现。开发者可调用show函数，定义并弹\\n\\n出日历选择器弹窗。\\n\\n#### 效果\\n\\n![PixPin_2024-12-26_23-21-28](HarmonyOS%20Next%20%E5%BC%B9%E7%AA%97%E7%B3%BB%E5%88%97%E6%95%99%E7%A8%8B%EF%BC%883%EF%BC%89.assets/PixPin_2024-12-26_23-21-28.gif)\\n\\n#### 示例代码\\n\\n1. 日历选择器弹窗主要通过  **CalendarPickerDialog.show** 方法来显示效果\\n2. 通过 **selected** 属性来显示当前选择的日期\\n3. 通过 **onAccept** 来获取当前选中的日期\\n\\n\`\`\`jsx\\n@Entry\\n@Component\\nstruct CalendarPickerDialogExample {\\n  // 声明一个私有属性selectedDate，类型为Date（日期类型），并初始化为2024年4月23日，用于记录用户选择的日期\\n  private selectedDate: Date = new Date('2024-04-23')\\n\\n  build() {\\n    Column() {\\n      Button(\\"Show CalendarPicker Dialog\\")\\n        .margin(20)\\n        .onClick(() => {\\n          // 调用CalendarPickerDialog的show方法来显示日历选择对话框，传入一个配置对象来定制对话框的相关样式和行为等属性\\n          CalendarPickerDialog.show({\\n            // 将当前组件中记录的selectedDate作为初始选中的日期传入日历选择对话框，这样对话框打开时就会默认选中这个日期\\n            selected: this.selectedDate,\\n            // 配置日历选择对话框中“确定”按钮的样式，通过设置字体颜色、字体大小、背景颜色和圆角半径等属性来定制外观\\n            acceptButtonStyle: {\\n              fontColor: '#2787d9',\\n              fontSize: '16fp',\\n              backgroundColor: '#f7f7f7',\\n              borderRadius: 10\\n            },\\n            // 配置日历选择对话框中“取消”按钮的样式，同样设置字体颜色、字体大小、背景颜色和圆角半径等属性，这里字体颜色使用框架中预定义的红色（Color.Red）\\n            cancelButtonStyle: {\\n              fontColor: Color.Red,\\n              fontSize: '16fp',\\n              backgroundColor: '#f7f7f7',\\n              borderRadius: 10\\n            },\\n            // 定义当用户点击“确定”按钮时的回调函数，接收用户选择的日期作为参数，将选择的日期赋值给组件内的selectedDate属性，\\n            // 这样当对话框下次再次弹出时，就会显示上一次确定选择的日期作为初始选中日期\\n            onAccept: (date: Date) => {\\n              this.selectedDate = date;\\n            }\\n          });\\n        })\\n    }\\n    .width('100%')\\n  }\\n}\\n\`\`\`\\n\\n#### 参考API\\n\\n[链接](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides-V5/arkts-fixes-style-dialog-V5#%E6%97%A5%E6%9C%9F%E6%BB%91%E5%8A%A8%E9%80%89%E6%8B%A9%E5%99%A8%E5%BC%B9%E7%AA%97-datepickerdialog)\\n\\n\\n\\n## 日期滑动选择器弹窗 (DatePickerDialog)\\n\\n发者可以利用指定的日期范围，创建日期滑动选择器弹窗，将日期信息清晰地展示在弹出的窗口上。\\n\\n日期滑动选择器弹窗通过UIContext中的[showDatePickerDialog](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V5/js-apis-arkui-uicontext-V5#showdatepickerdialog)接口实现。\\n\\n而且还能通过属性来设置农历\\n\\n### 效果\\n\\n![PixPin_2024-12-27_08-37-11](HarmonyOS%20Next%20%E5%BC%B9%E7%AA%97%E7%B3%BB%E5%88%97%E6%95%99%E7%A8%8B%EF%BC%883%EF%BC%89.assets/PixPin_2024-12-27_08-37-11.gif)\\n\\n### 示例代码\\n\\n1. 通过**getUIContext** 的 showDatePickerDialog 方法来显示弹窗\\n2. 通过 **lunarSwitch** 属性来显示农历\\n\\n\`\`\`jsx\\n@Entry\\n@Component\\nstruct DatePickerDialogExample {\\n  @State selectTime: Date = new Date('2023-12-25T08:30:00');\\n\\n  build() {\\n    Column() {\\n      Button('showDatePickerDialog')\\n        .margin(30)\\n        .onClick(() => {\\n          this.getUIContext().showDatePickerDialog({\\n            start: new Date(\\"2000-1-1\\"),\\n            end: new Date(\\"2100-12-31\\"),\\n            selected: this.selectTime,\\n            lunarSwitch: true,\\n            showTime: true,\\n            onDateAccept: (value: Date) => {\\n              this.selectTime = value\\n              console.info(\\"DatePickerDialog:onAccept()\\" + JSON.stringify(value))\\n            },\\n          })\\n        })\\n    }.width('100%').margin({ top: 5 })\\n  }\\n}\\n\`\`\`\\n\\n### 参考API\\n\\n[链接](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides-V5/arkts-fixes-style-dialog-V5#%E6%96%87%E6%9C%AC%E6%BB%91%E5%8A%A8%E9%80%89%E6%8B%A9%E5%99%A8%E5%BC%B9%E7%AA%97-textpickerdialog)\\n\\n\\n\\n\\n\\n## 时间滑动选择器弹窗 (TimePickerDialog)\\n\\n开发者可根据24小时的时间区间，创建时间滑动选择器弹窗，将时间信息清晰地展示在弹出的窗口上。\\n\\n\\n\\n时间滑动选择器弹窗通过UIContext中的[showTimePickerDialog](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V5/js-apis-arkui-uicontext-V5#showtimepickerdialog)接口实现。\\n\\n### 效果\\n\\n![PixPin_2024-12-27_08-40-59](HarmonyOS%20Next%20%E5%BC%B9%E7%AA%97%E7%B3%BB%E5%88%97%E6%95%99%E7%A8%8B%EF%BC%883%EF%BC%89.assets/PixPin_2024-12-27_08-40-59.gif)\\n\\n### 示例代码\\n\\n1. 通过 textStyle 设置默认的文本样式\\n2. 通过 **selectedTextStyle** 设置选中的文本样式\\n3. 通过 **acceptButtonStyle**设置显示的按钮样式\\n\\n\`\`\`jsx\\n@Entry\\n@Component\\nstruct TimePickerDialogExample {\\n  @State selectTime: Date = new Date('2023-12-25T08:30:00');\\n\\n  build() {\\n    Column() {\\n      Button('showTimePickerDialog')\\n        .margin(30)\\n        .onClick(() => {\\n          this.getUIContext().showTimePickerDialog({\\n            selected: this.selectTime,\\n            textStyle: { color: '#2787d9', font: { size: '14fp', weight: FontWeight.Normal } },\\n            selectedTextStyle: { color: '#004aaf', font: { size: '18fp', weight: FontWeight.Regular } },\\n            acceptButtonStyle: {\\n              fontColor: '#2787d9',\\n              fontSize: '16fp',\\n              backgroundColor: '#f7f7f7',\\n              borderRadius: 10\\n            },\\n            cancelButtonStyle: {\\n              fontColor: Color.Red,\\n              fontSize: '16fp',\\n              backgroundColor: '#f7f7f7',\\n              borderRadius: 10\\n            }\\n          })\\n        })\\n    }.width('100%').margin({ top: 5 })\\n  }\\n}\\n\`\`\`\\n\\n\\n\\n### 参考API\\n\\n[链接](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides-V5/arkts-fixes-style-dialog-V5#%E6%97%B6%E9%97%B4%E6%BB%91%E5%8A%A8%E9%80%89%E6%8B%A9%E5%99%A8%E5%BC%B9%E7%AA%97-timepickerdialog)\\n\\n\\n\\n## 文本滑动选择器弹窗 (TextPickerDialog)\\n\\n开发者可根据指定的选择范围，创建文本滑动选择器弹窗，将文本信息清晰地展示在弹出的窗口上。\\n\\n文本滑动选择器弹窗通过UIContext中的[showTextPickerDialog](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V5/js-apis-arkui-uicontext-V5#showtextpickerdialog)接口实现。\\n\\n它比较典型的使用场景是**省市区选择器**\\n\\n### 效果\\n\\n![PixPin_2024-12-27_08-43-55](HarmonyOS%20Next%20%E5%BC%B9%E7%AA%97%E7%B3%BB%E5%88%97%E6%95%99%E7%A8%8B%EF%BC%883%EF%BC%89.assets/PixPin_2024-12-27_08-43-55.gif)\\n\\n### 示例代码\\n\\n1. 通过 range 设置 内容数组，格式可以参考代码\\n2. 通过 selected 来设置当前选中的range数组中的索引\\n\\n\`\`\`jsx\\n@Entry\\n@Component\\nstruct TextPickerDialogExample {\\n  private citys: TextCascadePickerRangeContent[] = [\\n    {\\n      text: '辽宁省',\\n      children: [{ text: '沈阳市', children: [{ text: '沈河区' }, { text: '和平区' }, { text: '浑南区' }] },\\n        { text: '大连市', children: [{ text: '中山区' }, { text: '金州区' }, { text: '长海县' }] }]\\n    },\\n    {\\n      text: '吉林省',\\n      children: [{ text: '长春市', children: [{ text: '南关区' }, { text: '宽城区' }, { text: '朝阳区' }] },\\n        { text: '四平市', children: [{ text: '铁西区' }, { text: '铁东区' }, { text: '梨树县' }] }]\\n    },\\n    {\\n      text: '黑龙江省',\\n      children: [{ text: '哈尔滨市', children: [{ text: '道里区' }, { text: '道外区' }, { text: '南岗区' }] },\\n        { text: '牡丹江市', children: [{ text: '东安区' }, { text: '西安区' }, { text: '爱民区' }] }]\\n    }\\n  ]\\n  private select: number = 0;\\n\\n  build() {\\n    Column() {\\n      Button('showTextPickerDialog')\\n        .margin(30)\\n        .onClick(() => {\\n          this.getUIContext().showTextPickerDialog({\\n            range: this.citys,\\n            selected: this.select,\\n            onAccept: (value: TextPickerResult) => {\\n              this.select = value.index as number\\n            }\\n          })\\n        })\\n    }.width('100%').margin({ top: 5 })\\n  }\\n}\\n\`\`\`\\n\\n### 参考API\\n\\n[链接](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides-V5/arkts-fixes-style-dialog-V5#%E6%96%87%E6%9C%AC%E6%BB%91%E5%8A%A8%E9%80%89%E6%8B%A9%E5%99%A8%E5%BC%B9%E7%AA%97-textpickerdialog)\\n\\n\\n\\n## 生命周期\\n\\n以上的弹窗组件都提供了如下的生命周期，开发者可以根据需求自行定义使用\\n\\n生命周期的触发顺序可看各组件API参考。\\n\\n| 名称            | 类型       | 说明                       |\\n| :-------------- | :--------- | :------------------------- |\\n| onDidAppear     | () => void | 弹窗弹出时的事件回调。     |\\n| onDidDisappear  | () => void | 弹窗消失时的事件回调。     |\\n| onWillAppear    | () => void | 弹窗显示动效前的事件回调。 |\\n| onWillDisappear | () => void | 弹窗退出动效前的事件回调。 |\\n\\n## 总结\\n\\n选择器弹窗提供了日常开发中尤其常见的场景，如果以上也满足不了需求，可以使用自定义弹窗来解决"}`),k={name:"鸿蒙开发技巧/HarmonyOS Next 弹窗系列教程/HarmonyOS Next 弹窗系列教程（3）/HarmonyOS Next 弹窗系列教程（3）.md"};function r(E,s,d,c,g,o){return a(),n("div",null,[...s[0]||(s[0]=[e("",53)])])}const F=i(k,[["render",r]]);export{b as __pageData,F as default};
